export const MONUMENTS = JSON.parse("[{\"id\":\"n1380870522\",\"kind\":\"memorial\",\"sub\":\"stele\",\"name\":\"броненосцу «Император Александр III»\",\"x\":-2935.2,\"z\":1084.8},{\"id\":\"n6085656252\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"x\":-2865.3,\"z\":778,\"subject\":\"Q7200;Q4190651\",\"inscription\":\"В этом доме бывал в 1819-1820 гг. А.С. Пушкин на собраниях литературно-политического кружка \\\"Зелёная лампа\\\"\"},{\"id\":\"n8833398951\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"М. Е. Лобашеву\",\"x\":-3002.3,\"z\":1017.8,\"subject\":\"Q4264718\",\"inscription\":\"В этом доме с 1934 по 1971 год жил и работал выдающийся генетик, ученый и педагог Михаил Ефимович Лобашев\"},{\"id\":\"n8952171657\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Е. Ю. Учителю\",\"x\":-3045.2,\"z\":945.9,\"subject\":\"Q13218090\",\"inscription\":\"Ефим Юльевич Учитель, кинорежиссер, Народный артист СССР работал с 1935 по 1988 год на Ленинградской студии документальных фильмов\"},{\"id\":\"n8980831248\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Н. А. Тырсе\",\"x\":-2940.1,\"z\":963.1,\"subject\":\"Q6690711\",\"inscription\":\"В этом доме жил и работал с 1919 по 1942 г. Николай Андреевич Тырса, выдающийся художник и педагог\"},{\"id\":\"n9301441631\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"x\":-3268.4,\"z\":1172.2},{\"id\":\"n10240871805\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"x\":-2952.9,\"z\":935.3,\"inscription\":\"В этом доме с 1808 по 1958 год жили представители семей Бенуа, Лансере, Серебряковых, давших миру выдающихся архитекторов, художников, скульпторов и историков искусства\"},{\"id\":\"n11282005592\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"x\":-3160.9,\"z\":1111.8,\"inscription\":\"Здесь размещались казармы гвардейского экипажа, моряки которого во главе с декабристами Н.А. Бестужевым и А.П. Арбузовым вышли на Сенатскую площадь в день восстания против самодержавия 14 (26) декабря 1825 года\"},{\"id\":\"n13254807508\",\"kind\":\"artwork\",\"sub\":\"mural\",\"x\":-2849.5,\"z\":898.8},{\"id\":\"n13254807522\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"x\":-2988.2,\"z\":1012.2},{\"id\":\"n8980845364\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Училищу корабельной архитектуры\",\"x\":-2774.8,\"z\":961,\"inscription\":\"Здесь в 1798-1816 годах размещалось первое в мире Училище корабельной архитектуры\"},{\"id\":\"n13254807515\",\"kind\":\"artwork\",\"sub\":\"mural\",\"x\":-2831.4,\"z\":883.4},{\"id\":\"n6653419462\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Первый петербургский комитет Почтово-телеграфного союза\",\"x\":-3432.1,\"z\":920.7,\"inscription\":\"Здесь в 1905 г. помещался первый петербургский комитет Почтово-телеграфного союза\"},{\"id\":\"n6653419465\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"С. А. Евсееву\",\"x\":-3453.1,\"z\":1018.6,\"subject\":\"Q104173628\",\"inscription\":\"В этом доме с 1909 г. по 1959 г. жил и работал известный советский скульптор, создатель памятника Владимиру Ильичу Ленину у Финляндского вокзала в Ленинграде Сергей Александрович Евсеев\"},{\"id\":\"n6439061015\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"М. С. Цвету\",\"x\":-3603.1,\"z\":1083.5,\"subject\":\"Q241118\",\"inscription\":\"В этом здании в 1897-1902 годах жил и работал выдающийся русский учёный, основатель хроматографии Михаил Семёнович Цвет\"},{\"id\":\"n6572268579\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"заседания Центрального и Петербургского комитетов РСДРП\",\"x\":-3692.2,\"z\":1101.6,\"inscription\":\"В этом доме в 1905 – 1906 годах проходили заседания Центрального и Петербургского комитетов РСДРП а также различные партийные совещания и конференции под руководством В. И. Ленина\"},{\"id\":\"n6572283986\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Ю. М. Шокальскому\",\"x\":-3687.6,\"z\":1112.4,\"subject\":\"Q1672306\",\"inscription\":\"Здесь жил, работал и скончался русский географ, почётный академик Юлий Михайлович Шокальский. Род. в 1856 году, сконч. в 1940 году.\"},{\"id\":\"n7567481762\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"А. А. Блоку\",\"x\":-3871.5,\"z\":995.8,\"subject\":\"Q164765\"},{\"id\":\"n8939490851\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"И. Н. Вознесенскому\",\"x\":-3746.6,\"z\":924.8,\"subject\":\"Q19907625\",\"inscription\":\"В этом доме с 1923 года по 1946 год жил выдающийся ученый-инженер, создатель отечественного гидротурбостроения Иван Николаевич Вознесенский\"},{\"id\":\"n10116777537\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"x\":-3626.4,\"z\":1094.8,\"inscription\":\"Пролетарии всех стран, соединяйтесь! В этом доме помещался в 1905 году первый союз рабочих печатного дела г. С.-Петербурга\"},{\"id\":\"n13288927243\",\"kind\":\"memorial\",\"sub\":\"statue\",\"name\":\"А. А. Блоку\",\"x\":-3761.9,\"z\":963.5,\"material\":\"bronze\",\"startDate\":\"2023-01-06\",\"subject\":\"Блок, Александр Александрович\",\"artist\":\"Е. Н. Ротанов; И. В. Кожин\"},{\"id\":\"n14015779782\",\"kind\":\"artwork\",\"x\":-3898.8,\"z\":1090.4},{\"id\":\"n2002969021\",\"kind\":\"artwork\",\"sub\":\"statue\",\"name\":\"Венера Коломенская\",\"x\":-3844.1,\"z\":1151.9,\"artist\":\"Борис Семёнов\"},{\"id\":\"n7567481756\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"В. И. Ермаку\",\"x\":-3958.5,\"z\":1159.2,\"subject\":\"Q3918576\",\"inscription\":\"Владимир Иванович Ермак, 1924-1943, герой Советского Союза, в бою под Ленинградом закрыл грудью амбразуру вражеского дзота\"},{\"id\":\"n2002969019\",\"kind\":\"artwork\",\"sub\":\"sculpture\",\"name\":\"Мать и дитя\",\"x\":-3893.1,\"z\":1199.6},{\"id\":\"n8942355929\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"М. К. Чюрлёнису\",\"x\":-3463.6,\"z\":1193.7,\"subject\":\"Q297137\",\"inscription\":\"В этом доме в 1908-1909 г. жил М. К. Чюрленис\"}]");
